function normalizeBrand(raw?: string | null): string {
  return String(raw || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

export function listPaintShadeBrands(): string[] {
  return [...new Set(PAINT_SHADE_CATALOG.map((s) => s.brand))].sort();
}

export function searchPaintShadeCatalog(
  query: string,
  options?: { brand?: string | null; limit?: number }
): CatalogPaintShade[] {
  const q = String(query || "")
    .toLowerCase()
    .trim();
  const brandNorm = normalizeBrand(options?.brand);
  const limit = Math.min(Math.max(options?.limit ?? 200, 1), 2000);

  let list = PAINT_SHADE_CATALOG;
  if (brandNorm) {
    const brandMatched = list.filter(
      (s) =>
        normalizeBrand(s.brand).includes(brandNorm) ||
        brandNorm.includes(normalizeBrand(s.brand))
    );
    if (brandMatched.length > 0) list = brandMatched;
  }

  if (!q) return list.slice(0, limit);

  const scored = list
    .map((s) => {
      const code = s.code.toLowerCase();
      const name = s.name.toLowerCase();
      const line = String(s.line || "").toLowerCase();
      const brand = s.brand.toLowerCase();
      let score = 0;
      if (code === q) score = 100;
      else if (code.startsWith(q)) score = 90;
      else if (code.includes(q)) score = 70;
      else if (name === q) score = 85;
      else if (name.startsWith(q)) score = 75;
      else if (name.includes(q)) score = 55;
      else if (line.includes(q) || brand.includes(q)) score = 30;
      else score = 0;
      return { s, score };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score || a.s.code.localeCompare(b.s.code));

  return scored.slice(0, limit).map((x) => x.s);
}
